        self.pila = []
        self.minimos = []

    def push(self, x):
        self.pila.append(x)
        if not self.minimos or x <= self.minimos[-1]:
            self.minimos.append(x)

    def pop(self):
        if self.pila:
            x = self.pila.pop()
            if x == self.minimos[-1]:
                self.minimos.pop()

